Let ${\mathcal F}$ be a separable Hilbert space, and let $\{A_t\}_{t \in [0,T]}, \{B_t\}_{t \in [0,T]}$ be time-indexed sequences of bounded operators $A_t : \mathbb{R}^p \to {\mathcal F}$ and $B_t : \mathbb{R}^p \to {\mathcal F}$ such that $t \mapsto A_t$ and $t \mapsto B_t$ are continuous in $[0,T]$.
Then,
\begin{align*}
\|\prod_{0}^T e^{-A_s A_s^{\top} ds} - \prod_{0}^T e^{-B_s B_s^{\top} ds}\| \leq (\sup_{t \in [0,T]} \|A_t - B_t\|) (2\sqrt{T} + 3T \cdot {\mathcal V}(\{A_t - B_t\}_{t \in [0,T]}))\,.\end{align*}

The unique solution to the integral equation (12) is given as follows. For any $0 \leq x \leq y \leq T$ define $s_{m,j} = (y-x)(j/m) + x$ and $\delta = (y-x) / m$, and let $P(y,x)$ be the product integral 
\begin{align*}
P(y,x) := \prod_{x}^y e^{-K_s ds} := \lim_{m \to \infty} \prod_{j=1}^m e^{-\delta K_{s_j}} = \lim_{m \to \infty} e^{-\delta K_{s_m}} e^{-\delta K_{s_{m-1}}} \dots e^{-\delta K_{s_2}} e^{-\delta K_{s_1}}\,.
\end{align*}

For any time $t$,
\begin{align*}
\|{\boldsymbol w}(t) - {\boldsymbol w}_0\| \leq \sqrt{tR_0} / \alpha \quad \mbox{ and } \quad \|\bar{\boldsymbol w}(t) - {\boldsymbol w}_0\| &\leq \sqrt{tR_0} /\alpha\,.
\end{align*}
and furthermore
\begin{align}
\int_{0}^t \|\frac{d{\boldsymbol w}}{d\tau}\| d\tau \leq \sqrt{t R_0} / \alpha \quad \mbox{ and } \quad \int_{0}^t \|\frac{d\bar{\boldsymbol w}}{d\tau}\| d\tau \leq \sqrt{t R_0} / \alpha\,.\end{align}

For any time $0 \leq t \leq T$, we have $\|{\boldsymbol w}(t) - {\boldsymbol w}_0\| \leq \rho$.

For any time $0 \leq t \leq T$, we have
\begin{align*}
\|Dh({\boldsymbol w}(t)) - D\bar{h}(\bar{{\boldsymbol w}}(t))\| \leq \mathrm{Lip}(Dh) \sqrt{t R_0} / \alpha
\end{align*}

For any time $0 \leq t \leq T$, we have $\|K_t\| \leq 3\|Dh({\boldsymbol w}(0))\|^2 + 2\mathrm{Lip}(Dh)tR_0 / \alpha^2$.

The map $t \mapsto K_t$ is continuous (in the operator norm topology) in the interval $[0,T]$.

For any time-indexed sequence of matrices $(X_t)_{t \in [0,T]}$ in $\mathbb{R}^{n \times d}$ such that $t \mapsto X_t$ is continuous in $[0,T]$, and any $0 \leq a \leq b \leq T$,
\begin{align*}
\|e^{-X_bX_b^{\top} (b-a)} X_b - \left(\prod_{a}^b e^{-X_s X_s^{\top} ds}\right) X_a\| \leq 3 {\mathcal V}(\{X_s\}_{s \in [a,b]})
\end{align*}

For any $X,Y \in \mathbb{R}^{n \times d}$ (not necessarily symmetric)  and $t \geq 0$,
\begin{align*}
\|e^{-(X+Y)(X+Y)^{\top} t}(X+Y) - e^{-X X^{\top} t} X\| \leq 3\|Y\|\,.
\end{align*}

For any symmetric $X,Y \in \mathbb{R}^{n \times n}$ and $t \geq 0$,
\begin{align*}
\|e^{-(X+Y)^2 t}(X+Y) - e^{-X^2 t} X\| \leq 3\|Y\|
\end{align*}
